import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

import { afterNextRender, DestroyRef, Directive, ElementRef, inject } from '@angular/core';
import { ELEMENT_ORIGIN } from './elements';

/** ARIA role a native tag provides implicitly; custom elements need it spelled out. */
const ROLE: Record<string, string> = {
  button: 'button',
  a: 'link',
  ul: 'list',
  ol: 'list',
  li: 'listitem',
  nav: 'navigation',
  fieldset: 'group',
  table: 'table',
  thead: 'rowgroup',
  tbody: 'rowgroup',
  tfoot: 'rowgroup',
  tr: 'row',
  th: 'columnheader',
  td: 'cell',
};

const DISPLAY: Record<string, string> = {
  table: 'table',
  thead: 'table-header-group',
  tbody: 'table-row-group',
  tfoot: 'table-footer-group',
  tr: 'table-row',
  th: 'table-cell',
  td: 'table-cell',
  caption: 'table-caption',
};

/** Titles that are headings in the documented markup (`<h2 uiDialogTitle>`): keep the heading role on the element. */
const HEADINGS = new Set(['ui-dialog-title', 'ui-sheet-title', 'ui-alert-dialog-title', 'ui-drawer-title']);

const INLINE_ORIGINS = new Set(['span', 'a', 'button', 'label', 'kbd']);

let styled = false;
/**
 * Custom elements are `display: inline` by default. These defaults sit in `@layer base`, so Tailwind utilities (flex, grid,
 * hidden, …) always win, and `:not([hidden])` keeps the `hidden` attribute working.
 */
function ensureDefaultStyles(): void {
  if (styled || typeof document === 'undefined') return;
  styled = true;
  const groups = new Map<string, string[]>();
  for (const [alias, origin] of Object.entries(ELEMENT_ORIGIN)) {
    const d = DISPLAY[origin] ?? (INLINE_ORIGINS.has(origin) ? 'inline-block' : 'block');
    (groups.get(d) ?? groups.set(d, []).get(d)!).push(alias);
  }
  const css =
    [...groups].map(([d, list]) => `:where(${list.join(',')}):not([hidden]){display:${d}}`).join('\n') +
    '\n:where([data-slot][disabled]:not(:is(button,input,select,textarea,fieldset,optgroup,option))){pointer-events:none;opacity:.5}';
  const style = document.createElement('style');
  style.setAttribute('data-loomui-elements', '');
  style.textContent = `@layer base{\n${css}\n}`;
  document.head.appendChild(style);
}

const isDisabled = (el: HTMLElement) => el.hasAttribute('disabled') || el.getAttribute('aria-disabled') === 'true';

/**
 * Applied (as a host directive) to every Loom UI directive that also has a custom-element selector, e.g. <ui-button>.
 * On native elements it does nothing. On a custom element it restores what the native tag provided for free:
 *  - the implicit ARIA role and, for buttons/links, a tab stop;
 *  - Enter / Space activation for button-like elements (Enter for links), skipped when the component already handled the key;
 *  - `href` navigation for link-like elements, `for` association for label-like elements.
 * Directives keep full control: anything they set themselves (role, tabindex, …) is never overwritten.
 */
@Directive()
export class UiElementHost {
  private readonly el = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;

  constructor() {
    const name = this.el.localName;
    const origin = ELEMENT_ORIGIN[name];
    if (origin === undefined) return; // native element or an element without a mapping
    ensureDefaultStyles();
    const destroy = inject(DestroyRef);

    afterNextRender(() => {
      const el = this.el;
      const role = ROLE[origin];
      if (role && !el.hasAttribute('role')) el.setAttribute('role', role);
      if ((origin === 'button' || origin === 'a') && !el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');
      if (HEADINGS.has(name) && !el.hasAttribute('role')) {
        el.setAttribute('role', 'heading');
        if (!el.hasAttribute('aria-level')) el.setAttribute('aria-level', '2');
      }

      const off: (() => void)[] = [];
      const on = <K extends keyof HTMLElementEventMap>(type: K, fn: (e: HTMLElementEventMap[K]) => void) => {
        el.addEventListener(type, fn);
        off.push(() => el.removeEventListener(type, fn));
      };

      if (origin === 'button' || origin === 'a') {
        let spaceDown = false;
        on('keydown', (e) => {
          if (e.target !== el || e.defaultPrevented || isDisabled(el)) return;
          if (e.key === 'Enter') {
            e.preventDefault();
            el.click();
          } else if (e.key === ' ' && origin === 'button') {
            e.preventDefault(); // no page scroll; activate on keyup like a native button
            spaceDown = true;
          }
        });
        on('keyup', (e) => {
          if (e.key === ' ' && spaceDown && e.target === el && !isDisabled(el)) {
            spaceDown = false;
            el.click();
          }
        });
      }

      if (origin === 'a') {
        on('click', (e) => {
          const href = el.getAttribute('href');
          if (e.defaultPrevented || !href || isDisabled(el)) return;
          const target = el.getAttribute('target');
          if (target === '_blank') window.open(href, '_blank', 'noopener');
          else window.location.assign(href);
        });
      }

      if (origin === 'label') {
        on('click', (e) => {
          const id = el.getAttribute('for');
          if (!id || e.defaultPrevented) return;
          const t = e.target as HTMLElement;
          if (t.closest('button, input, select, textarea, a, [role=checkbox], [role=switch], [role=radio]')) return;
          const control = document.getElementById(id);
          if (!control) return;
          if (['INPUT', 'TEXTAREA', 'SELECT'].includes(control.tagName) && (control as HTMLInputElement).type !== 'checkbox' && (control as HTMLInputElement).type !== 'radio') control.focus();
          else control.click();
        });
      }

      destroy.onDestroy(() => off.forEach((f) => f()));
    });
  }
}

export * from './cn';
export * from './overlay-helpers';
export * from './layer';
export * from './popper';
export * from './modal';
export * from './menu';
export * from './elements';
export * from './element-host';
export * from './native-control';

import { Directive, effect, model, signal, untracked } from '@angular/core';
import { nextId, whenAnimationDone } from './overlay-helpers';

/**
 * State holder shared by every overlay root (Dialog, Sheet, Popover, DropdownMenu, Select, Tooltip).
 * `open` is the source of truth; `mounted` stays true until the exit animation finishes so the content can
 * play tw-animate-css `animate-out` with data-state="closed" (observed on the live site).
 */
@Directive()
export abstract class UiLayerRoot {
  readonly open = model(false);
  readonly id = nextId('ui-layer');
  readonly mounted = signal(false);
  readonly state = signal<'open' | 'closed'>('closed');
  readonly trigger = signal<HTMLElement | null>(null);
  readonly contentEl = signal<HTMLElement | null>(null);
  /** Virtual anchor (context menus open at the pointer instead of a trigger element). */
  readonly anchorPoint = signal<{ x: number; y: number } | null>(null);
  /** Panes of nested layers (sub-menus): clicks inside them are not "outside" for this layer. */
  readonly childPanes = new Set<HTMLElement>();

  constructor() {
    effect(() => {
      const open = this.open();
      untracked(() => {
        if (open) {
          this.mounted.set(true);
          this.state.set('open');
        } else if (this.mounted()) {
          this.state.set('closed');
          void whenAnimationDone(this.contentEl()).then(() => {
            if (!this.open()) this.mounted.set(false);
          });
        }
      });
    });
  }

  toggle(): void {
    this.open.update((v) => !v);
  }
  close(): void {
    this.open.set(false);
  }
}

import { FocusableOption, FocusKeyManager } from '@angular/cdk/a11y';
import {
  booleanAttribute,
  Directive,
  ElementRef,
  inject,
  InjectionToken,
  input,
  output,
  signal,
  WritableSignal,
} from '@angular/core';
import { Directionality } from '@angular/cdk/bidi';
import { UiLayerRoot } from './layer';
import { UiPopperContentBase } from './popper';

/**
 * Shared kit behind DropdownMenu, ContextMenu and Menubar (Radix Menu equivalent): items, sub-menus, roving focus,
 * typeahead and keyboard rules live here; the three components only add their own roots, triggers and classes.
 */
export class UiMenuSelectEvent {
  defaultPrevented = false;
  preventDefault(): void {
    this.defaultPrevented = true;
  }
}

/** What an item/content needs from "its" menu (a root menu or a sub-menu). */
export interface MenuCtx {
  readonly manager: WritableSignal<FocusKeyManager<UiMenuItemBase> | null>;
  readonly contentEl: WritableSignal<HTMLElement | null>;
  readonly childPanes: Set<HTMLElement>;
  readonly dirIsRtl: () => boolean;
  /** Close the whole menu tree (after selecting an item). */
  closeAll(): void;
  /** Menubar: ArrowLeft/Right inside an open menu moves to the neighbouring menu. */
  horizontal?(dir: 'prev' | 'next'): void;
}
export const UI_MENU_CTX = new InjectionToken<MenuCtx>('UI_MENU_CTX');
export const UI_MENU_ITEM = new InjectionToken<UiMenuItemBase>('UI_MENU_ITEM');
export const UI_MENU_SUB = new InjectionToken<UiMenuSubBase>('UI_MENU_SUB');

@Directive()
export abstract class UiMenuRootBase extends UiLayerRoot implements MenuCtx {
  /** Set by the trigger when opened with the keyboard so the content can focus the first/last item. */
  keyboardOpen: 'first' | 'last' | null = null;
  readonly manager = signal<FocusKeyManager<UiMenuItemBase> | null>(null);
  readonly triggerId = signal<string>('');
  private readonly directionality = inject(Directionality);
  dirIsRtl = (): boolean => this.directionality.value === 'rtl';
  closeAll(): void {
    this.close();
  }
}

@Directive()
export abstract class UiMenuItemBase implements FocusableOption {
  readonly ctx = inject(UI_MENU_CTX);
  protected readonly el = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  readonly disabledInput = input(false, { alias: 'disabled', transform: booleanAttribute });
  readonly select = output<UiMenuSelectEvent>();
  readonly highlighted = signal(false);
  readonly userClass = input<string>('', { alias: 'class' });

  get disabled(): boolean {
    return this.disabledInput();
  }
  focus(): void {
    this.el.focus();
  }
  getLabel(): string {
    return (this.el.textContent ?? '').trim();
  }
  protected onFocus(): void {
    this.highlighted.set(true);
  }
  protected onBlur(): void {
    this.highlighted.set(false);
  }
  protected onPointerMove(): void {
    if (this.disabled || this.highlighted()) return;
    const m = this.ctx.manager();
    if (m) m.setActiveItem(this as UiMenuItemBase);
    else this.focus();
  }
  protected onPointerLeave(): void {
    if (this.highlighted() && !this.keepFocusOnLeave()) this.ctx.contentEl()?.focus();
  }
  protected keepFocusOnLeave(): boolean {
    return false;
  }
  /** Run by click or Enter/Space. */
  activate(): void {
    if (this.disabled) return;
    this.beforeSelect();
    const ev = new UiMenuSelectEvent();
    this.select.emit(ev);
    if (!ev.defaultPrevented) this.ctx.closeAll();
  }
  protected beforeSelect(): void {}
  /** Sub-menu triggers override to open on ArrowRight/ArrowLeft (direction-aware). */
  openOnArrow(): boolean {
    return false;
  }
}

/** Host bindings shared by every menu item directive (spread into `host`; override `data-slot`). */
export const MENU_ITEM_HOST = {
  tabindex: '-1',
  '[attr.data-disabled]': 'disabled ? "" : null',
  '[attr.aria-disabled]': 'disabled ? "true" : null',
  '[attr.data-highlighted]': 'highlighted() ? "" : null',
  '(focus)': 'onFocus()',
  '(blur)': 'onBlur()',
  '(pointermove)': 'onPointerMove()',
  '(pointerleave)': 'onPointerLeave()',
  '(click)': 'activate()',
};

/** A sub-menu root: it is itself a menu context nested in its parent's. */
@Directive()
export abstract class UiMenuSubBase extends UiMenuRootBase {
  readonly parent = inject(UI_MENU_CTX, { skipSelf: true });
  override closeAll(): void {
    this.parent.closeAll();
  }
  override dirIsRtl = (): boolean => this.parent.dirIsRtl();
}

@Directive()
export abstract class UiMenuSubTriggerBase extends UiMenuItemBase {
  protected readonly sub = inject(UI_MENU_SUB);
  /** The trigger is an item of the PARENT menu (the nearest UI_MENU_CTX is the sub-menu it opens). */
  override readonly ctx: MenuCtx = this.sub.parent;
  private timer: ReturnType<typeof setTimeout> | undefined;

  constructor() {
    super();
    this.sub.trigger.set(this.el);
  }
  override activate(): void {
    if (this.disabled) return;
    this.sub.keyboardOpen = 'first';
    this.sub.open.set(true);
  }
  override openOnArrow(): boolean {
    this.activate();
    return true;
  }
  protected override keepFocusOnLeave(): boolean {
    return this.sub.open();
  }
  protected override onPointerMove(): void {
    super.onPointerMove();
    if (this.disabled || this.sub.open()) return;
    clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.sub.keyboardOpen = null;
      this.sub.open.set(true);
    }, 100);
  }
}

@Directive()
export abstract class UiMenuContentBase extends UiPopperContentBase {
  protected abstract readonly menu: UiMenuRootBase;
  protected abstract menuItems(): readonly UiMenuItemBase[];
  private manager: FocusKeyManager<UiMenuItemBase> | null = null;

  /** Content of a sub-menu closes itself on the "back" arrow. */
  protected isSub = false;

  protected override onAttached(): void {
    const items = this.menuItems().filter((i) => i.ctx === (this.menu as MenuCtx));
    this.manager = new FocusKeyManager<UiMenuItemBase>([...items])
      .withVerticalOrientation()
      .withHomeAndEnd()
      .withTypeAhead(150)
      .skipPredicate((i) => i.disabled);
    this.menu.manager.set(this.manager);
    queueMicrotask(() => {
      if (this.menu.keyboardOpen === 'first') this.manager?.setFirstItemActive();
      else if (this.menu.keyboardOpen === 'last') this.manager?.setLastItemActive();
      else this.el.focus();
    });
  }

  protected override onDetached(): void {
    if (this.isSub) (this.menu as unknown as { parent: MenuCtx }).parent.childPanes.delete(this.el);
    this.manager = null;
    this.menu.manager.set(null);
    this.menu.keyboardOpen = null;
  }

  protected onMenuKeydown(e: KeyboardEvent): void {
    if (e.key === 'Tab') return e.preventDefault(); // Radix menus keep focus inside; Tab does nothing
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      this.manager?.activeItem?.activate();
      return;
    }
    const rtl = this.menu.dirIsRtl();
    const forward = rtl ? 'ArrowLeft' : 'ArrowRight';
    const back = rtl ? 'ArrowRight' : 'ArrowLeft';
    if (e.key === forward) {
      const item = this.manager?.activeItem;
      if (item?.openOnArrow()) {
        e.preventDefault();
        return;
      }
      if (!this.isSub) {
        e.preventDefault();
        (this.menu as MenuCtx).horizontal?.('next');
      }
      return;
    }
    if (e.key === back) {
      e.preventDefault();
      if (this.isSub) this.menu.close();
      else (this.menu as MenuCtx).horizontal?.('prev');
      return;
    }
    this.manager?.onKeydown(e);
  }

  protected override registerChildPane(): void {
    if (this.isSub) {
      const parent = (this.menu as unknown as { parent: MenuCtx }).parent;
      parent.childPanes.add(this.el);
      this.menu.contentEl.set(this.el);
    }
  }
}

import { FocusTrap, FocusTrapFactory } from '@angular/cdk/a11y';
import { DomPortal } from '@angular/cdk/portal';
import { Overlay, OverlayRef } from '@angular/cdk/overlay';
import {
  DestroyRef,
  Directive,
  effect,
  ElementRef,
  inject,
  Injector,
  input,
  untracked,
} from '@angular/core';
import { UiLayerRoot } from './layer';
import { hideOthers } from './overlay-helpers';

/**
 * Shared engine for Dialog and Sheet (Radix Dialog equivalent); state lives in UiLayerRoot.
 * Contract (see docs/behavior-specs/dialog.md): portal to <body>, overlay + content as siblings, focus trap,
 * first tabbable focused on open, focus restored to the trigger on close, Esc / overlay click dismiss,
 * aria-hidden on everything else, body scroll lock, content stays mounted with data-state="closed"
 * until the exit animation finishes.
 */
@Directive()
export abstract class UiModalRoot extends UiLayerRoot {
  readonly titleId = `${this.id}H1`;
  readonly descriptionId = `${this.id}H2`;
}

export interface ModalContentConfig {
  slot: string;
  backdropClass: string;
  /** false for Alert Dialog: clicking the overlay does not dismiss. Default true. */
  closeOnBackdrop?: boolean;
  /** CSS selector of the element to focus on open (Alert Dialog focuses Cancel). Default: first tabbable. */
  initialFocusSelector?: string;
}

/** Base for the content directive: moves the host element into a CDK overlay while mounted. */
@Directive()
export abstract class UiModalContentBase {
  protected abstract readonly root: UiModalRoot;
  protected abstract readonly config: ModalContentConfig;

  protected readonly el = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  private readonly overlay = inject(Overlay);
  private readonly trapFactory = inject(FocusTrapFactory);
  private readonly injector = inject(Injector);
  private overlayRef: OverlayRef | null = null;
  private trap: FocusTrap | null = null;
  private restoreAria: (() => void) | null = null;
  private lastActive: HTMLElement | null = null;
  readonly userClass = input<string>('', { alias: 'class' });

  protected init(): void {
    this.el.hidden = true;
    this.root.contentEl.set(this.el);
    effect(
      () => {
        const mounted = this.root.mounted();
        untracked(() => (mounted ? this.attach() : this.detach()));
      },
      { injector: this.injector },
    );
    effect(
      () => {
        const state = this.root.state();
        this.overlayRef?.backdropElement?.setAttribute('data-state', state);
      },
      { injector: this.injector },
    );
    inject(DestroyRef).onDestroy(() => this.detach(false));
  }

  private attach(): void {
    if (this.overlayRef) return;
    this.lastActive = document.activeElement as HTMLElement | null;
    const ref = this.overlay.create({
      hasBackdrop: true,
      backdropClass: this.config.backdropClass.split(/\s+/).filter(Boolean),
      positionStrategy: this.overlay.position().global(),
      scrollStrategy: this.overlay.scrollStrategies.block(),
    });
    this.overlayRef = ref;
    ref.attach(new DomPortal(this.el));
    this.el.hidden = false;

    const backdrop = ref.backdropElement;
    backdrop?.setAttribute('data-slot', `${this.config.slot}-overlay`);
    backdrop?.setAttribute('data-state', 'open');
    backdrop?.setAttribute('aria-hidden', 'true');
    backdrop?.setAttribute('data-aria-hidden', 'true');

    ref.keydownEvents().subscribe((e) => {
      if (e.key === 'Escape' && !e.defaultPrevented) {
        e.preventDefault();
        this.root.close();
      }
    });
    if (this.config.closeOnBackdrop !== false) ref.backdropClick().subscribe(() => this.root.close());

    const container = ref.hostElement.parentElement as Element;
    this.restoreAria = hideOthers(container);
    document.body.setAttribute('data-scroll-locked', '1');

    this.trap = this.trapFactory.create(this.el);
    const preferred = this.config.initialFocusSelector ? this.el.querySelector<HTMLElement>(this.config.initialFocusSelector) : null;
    if (preferred) queueMicrotask(() => preferred.focus());
    else
      void this.trap.focusInitialElementWhenReady().then((ok) => {
        if (!ok) this.el.focus();
      });
  }

  private detach(restoreFocus = true): void {
    if (!this.overlayRef) return;
    this.trap?.destroy();
    this.trap = null;
    this.overlayRef.dispose();
    this.overlayRef = null;
    this.el.hidden = true;
    this.restoreAria?.();
    this.restoreAria = null;
    document.body.removeAttribute('data-scroll-locked');
    if (restoreFocus) (this.root.trigger() ?? this.lastActive)?.focus();
  }
}

import { booleanAttribute, computed, Directive, ElementRef, input, linkedSignal, signal, viewChild } from '@angular/core';
import type { ControlValueAccessor } from '@angular/forms';

/**
 * Base for the custom-element wrappers around native form controls (`<ui-input>`, `<ui-textarea>`, `<ui-native-select>`, …).
 * A custom element cannot be a form control, so the wrapper renders the real control inside its template (template ref
 * `#control`) and forwards the common attributes. It implements ControlValueAccessor, so `ngModel`, reactive forms and
 * `[(value)]`-style one-way binding keep working. `aria-label` / `aria-describedby` are forwarded to the inner control.
 */
// The id belongs on the inner control (so <label for> and aria-labelledby find it), not on the custom element.
@Directive({ host: { '[attr.id]': 'null' } })
export abstract class UiNativeControl implements ControlValueAccessor {
  readonly control = viewChild.required<ElementRef<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>>('control');

  readonly id = input<string>('');
  readonly name = input<string>('');
  readonly placeholder = input<string>('');
  /** Initial / one-way value. With forms, the form owns the value. */
  readonly value = input<string>('');
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly readonly = input(false, { transform: booleanAttribute });
  readonly required = input(false, { transform: booleanAttribute });
  readonly invalid = input(false, { transform: booleanAttribute });
  readonly autocomplete = input<string>('');
  readonly ariaLabel = input<string>('', { alias: 'aria-label' });
  readonly ariaDescribedby = input<string>('', { alias: 'aria-describedby' });
  readonly userClass = input<string>('', { alias: 'class' });

  protected readonly current = linkedSignal(() => this.value());
  private readonly cvaDisabled = signal(false);
  protected readonly isDisabled = computed(() => this.disabled() || this.cvaDisabled());

  private onChange: (v: string) => void = () => {};
  protected onTouched: () => void = () => {};

  focus(options?: FocusOptions): void {
    this.control().nativeElement.focus(options);
  }

  protected onInput(e: Event): void {
    const v = (e.target as HTMLInputElement).value;
    this.current.set(v);
    this.onChange(v);
  }

  writeValue(v: string | null): void {
    this.current.set(v ?? '');
  }
  registerOnChange(fn: (v: string) => void): void {
    this.onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }
  setDisabledState(d: boolean): void {
    this.cvaDisabled.set(d);
  }
}

let uidCounter = 0;
/** Unique, stable-per-session id like `ui-dialog-3`. */
export const nextId = (prefix: string): string => `${prefix}-${uidCounter++}`;

/**
 * Radix (via `aria-hidden`) hides everything outside a modal layer from assistive tech.
 * Marks every <body> child except the CDK overlay container with aria-hidden + data-aria-hidden,
 * and returns a function that restores the previous state.
 */
export function hideOthers(keep: Element): () => void {
  const changed: { el: Element; prev: string | null }[] = [];
  for (const el of Array.from(document.body.children)) {
    if (el === keep || el.contains(keep) || el.tagName === 'SCRIPT') continue;
    changed.push({ el, prev: el.getAttribute('aria-hidden') });
    el.setAttribute('aria-hidden', 'true');
    el.setAttribute('data-aria-hidden', 'true');
  }
  return () => {
    for (const { el, prev } of changed) {
      el.removeAttribute('data-aria-hidden');
      if (prev === null) el.removeAttribute('aria-hidden');
      else el.setAttribute('aria-hidden', prev);
    }
  };
}

/**
 * Resolves when the element's CSS animations (tw-animate-css `animate-out`) have finished, or after a
 * fallback timeout so we never keep an overlay mounted forever (reduced motion, no animation, hidden tab).
 */
export function whenAnimationDone(el: HTMLElement | null, fallbackMs = 250): Promise<void> {
  return new Promise((resolve) => {
    if (!el) return resolve();
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      el.removeEventListener('animationend', onEnd);
      el.removeEventListener('animationcancel', onEnd);
      clearTimeout(timer);
      resolve();
    };
    const onEnd = (e: Event) => {
      if (e.target === el) finish();
    };
    el.addEventListener('animationend', onEnd);
    el.addEventListener('animationcancel', onEnd);
    const timer = setTimeout(finish, fallbackMs);
    const running = typeof el.getAnimations === 'function' ? el.getAnimations().length : 0;
    if (!running) finish();
  });
}

import { Directionality } from '@angular/cdk/bidi';
import {
  ConnectedPosition,
  ConnectedOverlayPositionChange,
  Overlay,
  OverlayRef,
} from '@angular/cdk/overlay';
import { DomPortal } from '@angular/cdk/portal';
import { DestroyRef, Directive, effect, ElementRef, inject, Injector, input, untracked } from '@angular/core';
import { UiLayerRoot } from './layer';

export type Side = 'top' | 'right' | 'bottom' | 'left';
export type Align = 'start' | 'center' | 'end';

interface Meta {
  side: Side;
  align: Align;
}

const OPPOSITE: Record<Side, Side> = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };

/** Preferred placement first, then the opposite side as a flip fallback (what Radix/floating-ui do). */
export function buildPositions(
  side: Side,
  align: Align,
  sideOffset: number,
  rtl: boolean,
): { positions: ConnectedPosition[]; meta: WeakMap<ConnectedPosition, Meta> } {
  const meta = new WeakMap<ConnectedPosition, Meta>();
  const make = (s: Side): ConnectedPosition => {
    let p: ConnectedPosition;
    const xAlign = align === 'center' ? 'center' : align; // logical start/end (flips with dir like floating-ui)
    if (s === 'bottom' || s === 'top') {
      p = {
        originX: xAlign,
        originY: s === 'bottom' ? 'bottom' : 'top',
        overlayX: xAlign,
        overlayY: s === 'bottom' ? 'top' : 'bottom',
        offsetY: s === 'bottom' ? sideOffset : -sideOffset,
      };
    } else {
      const yAlign = align === 'start' ? 'top' : align === 'end' ? 'bottom' : 'center';
      // physical left/right regardless of direction
      const outerX = (s === 'right') !== rtl ? 'end' : 'start';
      const innerX = outerX === 'end' ? 'start' : 'end';
      p = {
        originX: outerX,
        originY: yAlign,
        overlayX: innerX,
        overlayY: yAlign,
        offsetX: s === 'right' ? sideOffset : -sideOffset,
      };
    }
    meta.set(p, { side: s, align });
    return p;
  };
  return { positions: [make(side), make(OPPOSITE[side])], meta };
}

function transformOrigin(side: Side, align: Align): string {
  const x = align === 'start' ? 'left' : align === 'end' ? 'right' : 'center';
  const y = align === 'start' ? 'top' : align === 'end' ? 'bottom' : 'center';
  if (side === 'bottom') return `${x} top`;
  if (side === 'top') return `${x} bottom`;
  if (side === 'right') return `left ${y}`;
  return `right ${y}`;
}

/**
 * Base for popper-based content (Popover, DropdownMenu, Select, Tooltip). The host element is declared inline,
 * hidden, and moved into a CDK connected overlay (DomPortal) while `root.mounted()`.
 */
@Directive()
export abstract class UiPopperContentBase {
  protected abstract readonly root: UiLayerRoot;
  /** CSS custom-property prefix used by shadcn classes, e.g. `--radix-popover`. */
  protected abstract readonly varPrefix: string;

  readonly side = input<Side>('bottom');
  readonly align = input<Align>('center');
  readonly sideOffset = input(4);
  readonly userClass = input<string>('', { alias: 'class' });

  protected readonly el = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  protected readonly overlay = inject(Overlay);
  protected readonly dir = inject(Directionality);
  protected readonly injector = inject(Injector);
  protected overlayRef: OverlayRef | null = null;
  private lastActive: HTMLElement | null = null;

  /** Hook for subclasses. Return false to skip default focus handling. */
  protected onAttached(): void {}
  protected onDetached(): void {}
  /** Whether outside pointer / Esc should close. Tooltip overrides to false. */
  protected closeOnOutside = true;
  protected restoreFocusOnClose = true;
  protected matchTriggerWidth = false;

  protected init(): void {
    this.el.hidden = true;
    this.root.contentEl.set(this.el);
    effect(
      () => {
        const mounted = this.root.mounted();
        untracked(() => (mounted ? this.attach() : this.detach()));
      },
      { injector: this.injector },
    );
    inject(DestroyRef).onDestroy(() => this.detach(false));
  }

  private attach(): void {
    const trigger = this.root.trigger();
    const point = this.root.anchorPoint();
    if (this.overlayRef || (!trigger && !point)) return;
    this.lastActive = document.activeElement as HTMLElement | null;
    const rtl = this.dir.value === 'rtl';
    const { positions, meta } = buildPositions(this.side(), this.align(), this.sideOffset(), rtl);
    const strategy = this.overlay
      .position()
      .flexibleConnectedTo(point ?? trigger!)
      .withPositions(positions)
      .withPush(false)
      .withFlexibleDimensions(false)
      .withViewportMargin(8);
    const ref = this.overlay.create({
      positionStrategy: strategy,
      scrollStrategy: this.overlay.scrollStrategies.reposition(),
      direction: this.dir.value,
      minWidth: this.matchTriggerWidth && trigger ? trigger.getBoundingClientRect().width : undefined,
    });
    this.overlayRef = ref;

    strategy.positionChanges.subscribe((c: ConnectedOverlayPositionChange) => {
      const m = meta.get(c.connectionPair);
      if (!m) return;
      this.el.setAttribute('data-side', m.side);
      this.el.setAttribute('data-align', m.align);
      this.setVars(m.side, m.align, trigger);
    });

    ref.attach(new DomPortal(this.el));
    this.el.hidden = false;
    this.el.setAttribute('data-side', this.side());
    this.el.setAttribute('data-align', this.align());
    this.setVars(this.side(), this.align(), trigger);
    this.registerChildPane();

    if (this.closeOnOutside) {
      ref.keydownEvents().subscribe((e) => {
        if (e.key === 'Escape' && !e.defaultPrevented) {
          e.preventDefault();
          this.root.close();
        }
      });
      ref.outsidePointerEvents().subscribe((e) => {
        const t = e.target as Node | null;
        if (t && trigger?.contains(t)) return; // trigger click handles its own toggle
        if (t && [...this.root.childPanes].some((pane) => pane.contains(t))) return;
        this.root.close();
      });
    }
    this.onAttached();
  }

  private detach(restoreFocus = true): void {
    if (!this.overlayRef) return;
    this.onDetached();
    this.overlayRef.dispose();
    this.overlayRef = null;
    this.el.hidden = true;
    if (restoreFocus && this.restoreFocusOnClose) (this.root.trigger() ?? this.lastActive)?.focus();
  }

  /** Hook: sub-menus register their pane with the parent layer. */
  protected registerChildPane(): void {}

  private setVars(side: Side, align: Align, trigger: HTMLElement | null): void {
    const r = trigger?.getBoundingClientRect() ?? new DOMRect(0, 0, 0, 0);
    const s = this.el.style;
    s.setProperty(`${this.varPrefix}-content-transform-origin`, transformOrigin(side, align));
    s.setProperty(`${this.varPrefix}-trigger-width`, `${r.width}px`);
    s.setProperty(`${this.varPrefix}-trigger-height`, `${r.height}px`);
    s.setProperty(`${this.varPrefix}-content-available-height`, `${window.innerHeight - 16}px`);
    s.setProperty(`${this.varPrefix}-content-available-width`, `${window.innerWidth - 16}px`);
  }
}
